import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DOMNodePointer_testNode_TriageGen1Test {

    private Node mockNode;
    private Node mockPI;

    @Before
    public void setUp() {
        mockNode = mock(Node.class);
        mockPI = mock(ProcessingInstruction.class);
    }

    @Test
    public void testNullTestReturnsTrue() {
        assertTrue(DOMNodePointer.testNode(mockNode, null));
    }

    @Test
    public void testNodeNameTest_ElementNodeMismatch() {
        Node nonElementNode = mock(Node.class);
        when(nonElementNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        NodeNameTest test = mock(NodeNameTest.class);
        assertFalse(DOMNodePointer.testNode(nonElementNode, test));
    }

    @Test
    public void testNodeNameTest_WildcardNoPrefix() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName(null, "any", null));
        assertTrue(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeNameTest_WildcardWithPrefix() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(true);
        when(test.getNodeName()).thenReturn(new QName("p", "any", null));

        // Mock static-like behavior via DOMNodePointer logic
        // Since we can't easily mock static methods without PowerMock, 
        // we assume DOMNodePointer.getNamespaceURI and getLocalName work with our mock.
        // In a real environment, these would interact with the node's underlying implementation.
        // For this test, we assume the internal logic passes if the namespace matches.

        // Note: Testing static methods logic requires the mock node to return specific values 
        // that DOMNodePointer.getNamespaceURI(node) uses.
        // Assuming DOMNodePointer.getNamespaceURI(node) calls node.getNamespaceURI()
        when(mockNode.getLocalName()).thenReturn("any");
        when(mockNode.getNamespaceURI()).thenReturn("http://test");
        when(test.getNamespaceURI()).thenReturn("http://test");

        assertTrue(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeNameTest_NameAndNamespaceMatch() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getLocalName()).thenReturn("target");
        when(mockNode.getNamespaceURI()).thenReturn("http://uri");

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("target"));
        when(test.getNamespaceURI()).thenReturn("http://uri");

        assertTrue(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeNameTest_NameMismatch() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getLocalName()).thenReturn("wrong");

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("target"));

        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeNameTest_NamespaceMismatch() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(mockNode.getLocalName()).thenReturn("target");
        when(mockNode.getNamespaceURI()).thenReturn("http://uri1");

        NodeNameTest test = mock(NodeNameTest.class);
        when(test.isWildcard()).thenReturn(false);
        when(test.getNodeName()).thenReturn(new QName("target"));
        when(test.getNamespaceURI()).thenReturn("http://uri2");

        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeTypeTest_Node() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.DOCUMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeTypeTest_Text() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_TEXT);

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.CDATA_SECTION_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeTypeTest_Comment() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_COMMENT);

        when(mockNode.getNodeType()).thenReturn(Node.COMMENT_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeTypeTest_PI() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(Compiler.NODE_TYPE_PI);

        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        assertTrue(DOMNodePointer.testNode(mockNode, test));

        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testNodeTypeTest_UnknownType() {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(999);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testProcessingInstructionTest_Success() {
        when(mockNode.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(mockPI.getTarget()).thenReturn("testTarget");
        // We must cast or mock the node to behave like a ProcessingInstruction
        // In the real code, it casts 'node' to 'ProcessingInstruction'
        // So we use a mock that implements both Node and ProcessingInstruction
        ProcessingInstruction piMock = mock(ProcessingInstruction.class);
        when(piMock.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(piMock.getTarget()).thenReturn("testTarget");

        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("testTarget");

        assertTrue(DOMNodePointer.testNode(piMock, test));
    }

    @Test
    public void testProcessingInstructionTest_WrongNodeType() {
        when(mockNode.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        assertFalse(DOMNodePointer.testNode(mockNode, test));
    }

    @Test
    public void testProcessingInstructionTest_MismatchTarget() {
        ProcessingInstruction piMock = mock(ProcessingInstruction.class);
        when(piMock.getNodeType()).thenReturn(Node.PROCESSING_INSTRUCTION_NODE);
        when(piMock.getTarget()).thenReturn("targetA");

        ProcessingInstructionTest test = mock(ProcessingInstructionTest.class);
        when(test.getTarget()).thenReturn("targetB");

        assertFalse(DOMNodePointer.testNode(piMock, test));
    }

    @Test
    public void testUnknownTestTypeReturnsFalse() {
        NodeTest unknownTest = mock(NodeTest.class);
        assertFalse(DOMNodePointer.testNode(mockNode, unknownTest));
    }
}
